export const EditorsNote: React.FC<EditorsNoteProps> = ({
  title: initialTitle = "From Akam editorial",
  note: initialNote = "This month we celebrate the voices shaping Malayalam literature today. Read slowly, share widely, and — if you have a story of your own write it. Every submission passes through our editorial board before it reaches you.",
}) => {
  const [data, setData] = useState({
    title: initialTitle,
    note: initialNote,
  });

  const [activeIndex, setActiveIndex] = useState(-1);
  const [isInView, setIsInView] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Scroll progress for the EditorsNote section relative to the viewport
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start end", "end start"],
  });

  // Map scroll progress (0 -> 1) directly to wheel rotation (-60deg -> 240deg) as user scrolls
  const wheelRotate = useTransform(scrollYProgress, [0, 1], [-60, 240]);
  const svgCounterRotate = useTransform(scrollYProgress, [0, 1], [60, -240]);

  // Fetch API note if using fallbacks
  useEffect(() => {
    setData({
      title: initialTitle,
      note: initialNote,
    });

    if (initialTitle !== "Editor's Note" && initialTitle !== "From Akam editorial") return;

    let isMounted = true;
    fetch(`${API_BASE_URL}/settings/editors-note`, {
      next: { revalidate: 60 },
    })
      .then((res) => (res.ok ? res.json() : null))
      .then((json) => {
        if (json && isMounted) {
          setData({
            title: json.title || initialTitle,
            note: json.note || initialNote,
          });
        }
      })
      .catch((err) => console.error("Failed to load Editor's Note settings", err));

    return () => {
      isMounted = false;
    };
  }, [initialTitle, initialNote]);

  // IntersectionObserver to trigger text animation once user enters view
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsInView(true);
        }
      },
      { threshold: 0.2 }
    );

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    return () => observer.disconnect();
  }, []);

  const words = data.note.split(" ");

  // Text animation runs word by word when user enters view
  useEffect(() => {
    if (!isInView) return;

    const interval = setInterval(() => {
      setActiveIndex((prev) => {
        if (prev < words.length) {
          return prev + 1;
        }
        clearInterval(interval);
        return prev;
      });
    }, 130);

    return () => clearInterval(interval);
  }, [isInView, words.length]);

  return (
    <section
      ref={containerRef}
      className="relative w-full overflow-hidden bg-[#D3F0E3] py-20 sm:py-28 font-poppins flex items-center justify-center "
    >
      {/* ── ROTATING HALF-CIRCLE CAROUSEL WHEEL (DRIVEN BY SCROLL) ── */}
      <div className="absolute top-1/2 -translate-y-1/2 right-[-140px] sm:right-[-180px] md:right-[-220px] w-[340px] h-[340px] sm:w-[440px] sm:h-[440px] md:w-[500px] md:h-[500px] pointer-events-none z-0">
        <motion.div
          style={{ rotate: wheelRotate }}
          className="w-full h-full relative"
        >
          {/* SVG 1: Top position on wheel */}
          <div className="absolute top-2 left-1/2 -translate-x-1/2 -translate-y-1/2">
            <motion.div style={{ rotate: svgCounterRotate }}>
              <MalayalamSvgOne className="w-24 sm:w-32 md:w-36 drop-shadow-sm" id="svg_wheel_1" />
            </motion.div>
          </div>

          {/* SVG 2: Left position on wheel (facing the text on screen) */}
          <div className="absolute left-2 top-1/2 -translate-y-1/2 -translate-x-1/2">
            <motion.div style={{ rotate: svgCounterRotate }}>
              <MalayalamSvgTwo className="w-24 sm:w-30 md:w-34 drop-shadow-sm" id="svg_wheel_2" />
            </motion.div>
          </div>

          {/* SVG 3: Bottom position on wheel */}
          <div className="absolute bottom-2 left-1/2 -translate-x-1/2 translate-y-1/2">
            <motion.div style={{ rotate: svgCounterRotate }}>
              <MalayalamSvgThree className="w-24 sm:w-30 md:w-34 drop-shadow-sm" id="svg_wheel_3" />
            </motion.div>
          </div>

          {/* SVG 4: Right position on wheel */}
          <div className="absolute right-2 top-1/2 -translate-y-1/2 translate-x-1/2">
            <motion.div style={{ rotate: svgCounterRotate }}>
              <MalayalamSvgTwo className="w-24 sm:w-30 md:w-34 drop-shadow-sm" id="svg_wheel_4" />
            </motion.div>
          </div>
        </motion.div>
      </div>
      {/* ── END ROTATING WHEEL CAROUSEL ── */}

      {/* Main Content Container */}
      <div className="container px-6 sm:px-10 max-w-3xl sm:max-w-4xl mx-auto relative z-10 text-center">
        {/* Section Title */}
        {data.title && (
          <h3 className="text-sm sm:text-base md:text-lg font-medium text-[#0FA975] tracking-wide mb-4 ">
            {data.title}
          </h3>
        )}

        {/* Word-by-Word Text Highlight Animation (Runs ONCE when in view) */}
        <p className="text-xl sm:text-2xl leading-relaxed  text-center tracking-tight flex flex-wrap justify-center">
          {words.map((word, i) => {
            const isHighlighted = i <= activeIndex;
            return (
              <span
                key={i}
                className="relative inline-block mr-[0.25em] my-[0.08em] select-none"
              >
                <motion.span
                  initial={false}
                  animate={{
                    opacity: isHighlighted ? 1 : 0.25,
                    color: isHighlighted ? "#111827" : "#4B5563",
                  }}
                  transition={{ duration: 0.25, ease: "easeOut" }}
                  className="font-medium sm:font-semibold"
                >
                  {word}
                </motion.span>
              </span>
            );
          })}
        </p>
      </div>
    </section>
  );
};

export default EditorsNote;
